import{_ as a,o as e,c as d,a0 as n}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"Home 页重设计与 Agent 沙箱 Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"archive/sandbox-specs/2026-05-12-home-redesign-agent-sandbox.md","filePath":"archive/sandbox-specs/2026-05-12-home-redesign-agent-sandbox.md"}'),s={name:"archive/sandbox-specs/2026-05-12-home-redesign-agent-sandbox.md"};function o(r,t,i,c,l,p){return e(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="home-页重设计与-agent-沙箱-dashboard" tabindex="-1">Home 页重设计与 Agent 沙箱 Dashboard <a class="header-anchor" href="#home-页重设计与-agent-沙箱-dashboard" aria-label="Permalink to &quot;Home 页重设计与 Agent 沙箱 Dashboard&quot;">​</a></h1><blockquote><p>状态: 设计阶段 | 关联: <code>2026-05-11-agent-sandbox-and-ecosystem-design.md</code> <code>2026-05-12-agent-sandbox-usage.md</code></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>以 AI Agent 安全沙箱为产品新主线重写 Home landing page (pages/index.vue)，并在 Dashboard 中增加 Agent 沙箱管理页面组（沙箱列表、接入令牌、流量审计）。</p><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>Home 页</strong>: Marketing landing page，双主线叙事——&quot;AI Agent 运行时&quot; + &quot;安全网络基础层&quot;</li><li><strong>Dashboard</strong>: 新增 Agent 沙箱管理分组，Dashboard 首页增加沙箱统计卡片</li></ul><hr><h2 id="一、home-页重设计" tabindex="-1">一、Home 页重设计 <a class="header-anchor" href="#一、home-页重设计" aria-label="Permalink to &quot;一、Home 页重设计&quot;">​</a></h2><h3 id="_1-1-hero-区" tabindex="-1">1.1 Hero 区 <a class="header-anchor" href="#_1-1-hero-区" aria-label="Permalink to &quot;1.1 Hero 区&quot;">​</a></h3><p><strong>Badge</strong>: <code>AI-Native Networking</code>（脉冲绿点保留）</p><p><strong>Title</strong>: &quot;AI Agent 的零信任运行环境&quot;</p><p><strong>Subtitle</strong>: &quot;Lattice 为每个 AI Agent 提供零特权沙箱隔离，通过 WireGuard 加密 Mesh 安全接入你的基础设施——从启动到组网，一条命令。&quot;</p><p><strong>CTA 双按钮</strong>:</p><ul><li>主按钮: <code>lattice-agent-sandbox start</code> → <code>/manage/stepper</code></li><li>次按钮: <code>查看控制台</code> → <code>/dashboard</code></li></ul><p><strong>Terminal mockup</strong> 展示沙箱启动和流量管控流程:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ lattice-agent-sandbox start --name my-agent</span></span>
<span class="line"><span>  → Creating gVisor sandbox...      ✓</span></span>
<span class="line"><span>  → Attaching WireGuard tunnel...   ✓</span></span>
<span class="line"><span>  → Registering with control plane.. ✓</span></span>
<span class="line"><span>  Agent &quot;my-agent&quot; is online at 10.100.0.5</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 合法外联 (白名单命中)</span></span>
<span class="line"><span>$ curl https://api.internal</span></span>
<span class="line"><span>  → PolicyCache.Allow() → ✓ → wireguard-go encrypt</span></span>
<span class="line"><span>  → P2P/Relay → 远端解密 → 200 OK</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 违规外联 (未命中)</span></span>
<span class="line"><span>$ curl https://evil.com</span></span>
<span class="line"><span>  → PolicyCache.Allow() → ✗ → EACCES</span></span>
<span class="line"><span>  → auditCh → POST /api/v1/audit/batch → 控制面告警</span></span></code></pre></div><p><strong>视觉效果</strong>: 保留后台 SVG 网络拓扑图 + 紫色 glow。终端窗口风格与当前一致（深色背景、macOS 红黄绿按钮、monospace 字体）。</p><h3 id="_1-2-features-区" tabindex="-1">1.2 Features 区 <a class="header-anchor" href="#_1-2-features-区" aria-label="Permalink to &quot;1.2 Features 区&quot;">​</a></h3><p>双行 3 列网格。上行 AI Agent 能力，下行网络基础能力。</p><table tabindex="0"><thead><tr><th>行</th><th>卡片</th><th>标题</th><th>描述</th><th>标签</th></tr></thead><tbody><tr><td>AI</td><td>1</td><td>零特权沙箱隔离</td><td>gVisor 用户态内核运行 Agent，无需 root/CAP_NET_ADMIN。每个 Agent 拥有独立 Go netstack，PID→TUN 绑定，外联全管控</td><td><code>stable</code></td></tr><tr><td>AI</td><td>2</td><td>Sidecar 外联拦截</td><td>seccomp notify + eBPF fast path 双重拦截。Agent 每次 socket 操作向 PolicyCache 查表，白名单命中直通，未命中→EACCES+审计</td><td><code>stable</code></td></tr><tr><td>AI</td><td>3</td><td>意图驱动网络管理</td><td>用自然语言描述网络需求——&quot;allow frontend to access api on 8080&quot;——AI 自动生成变更计划，Diff 预览后通过 RBAC 审批生效</td><td><code>roadmap</code></td></tr><tr><td>网络</td><td>4</td><td>WireGuard 加密 Mesh</td><td>NAT 穿透 P2P 直连 + LRP Relay 中继。WireGuard 端到端加密，ICE/STUN 自动打洞，跨集群桥接零配置</td><td><code>stable</code></td></tr><tr><td>网络</td><td>5</td><td>eBPF 高性能策略</td><td>内核态 LPM Trie + Port Hash 策略引擎，TC ingress/egress 挂载，百万规则级匹配。基础设施层东西向流量线速转发</td><td><code>roadmap</code></td></tr><tr><td>网络</td><td>6</td><td>全局流量审计</td><td>gVisor Go 层 + eBPF ring buffer 双路径汇聚，批量上报控制面 <code>POST /api/v1/audit/batch</code>，异常模式实时告警</td><td><code>stable</code></td></tr></tbody></table><p><strong>i18n key 模式</strong>: <code>landing.features.ai_sandbox</code>, <code>landing.features.ai_sidecar</code>, <code>landing.features.ai_intent</code>, <code>landing.features.net_wg</code>, <code>landing.features.net_ebpf</code>, <code>landing.features.net_audit</code></p><h3 id="_1-3-architecture-区" tabindex="-1">1.3 Architecture 区 <a class="header-anchor" href="#_1-3-architecture-区" aria-label="Permalink to &quot;1.3 Architecture 区&quot;">​</a></h3><p>双栏布局：左栏 Agent 沙箱生命周期步骤，右栏数据面 Terminal mockup。</p><p><strong>左栏：Agent 沙箱生命周期</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01  创建沙箱</span></span>
<span class="line"><span>    lattice-agent-sandbox start --name agent-1</span></span>
<span class="line"><span>    → 生成 WireGuard 密钥对</span></span>
<span class="line"><span>    → 创建 gVisor sandbox (OCI runtime)</span></span>
<span class="line"><span>    → Go netstack 接管网络栈</span></span>
<span class="line"><span></span></span>
<span class="line"><span>02  注册 + 策略注入</span></span>
<span class="line"><span>    → POST /api/v1/agent-isolation/register</span></span>
<span class="line"><span>    → 控制面创建 LatticePeer + AgentIdentity (Sandbox=gvisor)</span></span>
<span class="line"><span>    → 注入 PolicyChecker (白名单) + AuditWriter (审计 hook)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>03  Agent 运行</span></span>
<span class="line"><span>    → Agent 进程发起 socket → Sentry netstack 拦截</span></span>
<span class="line"><span>    → PolicyCache.Allow() 查表</span></span>
<span class="line"><span>    → 命中(allow): wireguard-go 加密 → P2P/Relay 发送 → 远端解密</span></span>
<span class="line"><span>    → 未命中(drop): EACCES 返回调用方 + audit event 上报</span></span></code></pre></div><p><strong>右栏：Terminal mockup（数据面路径）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 合法流量 (allow verdict path)</span></span>
<span class="line"><span>agent-1 socket → Sentry netstack → Allow</span></span>
<span class="line"><span>  → wireguard-go ChaCha20 encrypt</span></span>
<span class="line"><span>  → UDP :51820 → FilteringUDPMux</span></span>
<span class="line"><span>  → ICE P2P / LRP Relay → 远端 peer → decrypt → target</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 违规流量 (drop verdict path)</span></span>
<span class="line"><span>agent-1 socket → Sentry netstack → Deny → EACCES</span></span>
<span class="line"><span>  → ns.auditCh → AuditBatcher</span></span>
<span class="line"><span>  → POST /api/v1/audit/batch → 控制面告警</span></span></code></pre></div><p><strong>i18n key 模式</strong>: <code>landing.architecture.sandbox_step_1_title/desc</code>, etc.</p><h3 id="_1-4-pricing-区" tabindex="-1">1.4 Pricing 区 <a class="header-anchor" href="#_1-4-pricing-区" aria-label="Permalink to &quot;1.4 Pricing 区&quot;">​</a></h3><p>保留 Community / Pro 双栏布局。Feature 列表根据三层 Agent 沙箱能力更新。</p><p><strong>Community 栏</strong>:</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th></tr></thead><tbody><tr><td>1</td><td>WireGuard 加密 Mesh：无限节点</td></tr><tr><td>2</td><td>CRD 原生 K8s 控制器</td></tr><tr><td>3</td><td>NATS 信令 + ICE/STUN P2P 打洞</td></tr><tr><td>4</td><td>LRP Relay 中继</td></tr><tr><td>5</td><td>Agent 沙箱 (cgroup 模式)：PID 绑定 + 资源限制</td></tr><tr><td>6</td><td>Sidecar 外联拦截：seccomp + eBPF fast path</td></tr><tr><td>7</td><td>全局拓扑图可视化</td></tr><tr><td><s>8</s></td><td>(locked) gVisor 零特权沙箱隔离</td></tr><tr><td><s>9</s></td><td>(locked) eBPF 流量审计 + 异常告警</td></tr><tr><td><s>10</s></td><td>(locked) 意图引擎 (自然语言网络管理)</td></tr></tbody></table><p><strong>Pro 栏</strong>:</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th></tr></thead><tbody><tr><td>1</td><td>所有社区版功能</td></tr><tr><td>2</td><td>gVisor 零特权沙箱隔离：Go netstack 替代 TUN 设备</td></tr><tr><td>3</td><td>eBPF TC 策略引擎 (LPM/Port) + 流量镜像审计</td></tr><tr><td>4</td><td>意图引擎：自然语言网络变更计划</td></tr><tr><td>5</td><td>合规审计扫描 + 异常告警</td></tr><tr><td>6</td><td>Kubernetes 集群互联</td></tr><tr><td>7</td><td>SSO/OIDC + RBAC + 审批工作流</td></tr><tr><td>8</td><td>Firecracker MicroVM 沙箱 (远期增强)</td></tr></tbody></table><p><strong>i18n key 模式</strong>: <code>landing.pricing.community_feat_sandbox</code>, <code>landing.pricing.pro_feat_gvisor</code>, etc.</p><h3 id="_1-5-cta-区" tabindex="-1">1.5 CTA 区 <a class="header-anchor" href="#_1-5-cta-区" aria-label="Permalink to &quot;1.5 CTA 区&quot;">​</a></h3><ul><li><strong>Title</strong>: &quot;为你的 AI Agent 构建安全运行环境&quot;</li><li><strong>主按钮</strong>: <code>$ lattice-agent-sandbox start</code> → <code>/manage/stepper</code></li><li><strong>次按钮</strong>: <code>查看控制台</code> → <code>/dashboard</code></li><li><strong>Bottom badges</strong>: 零特权 / gVisor 隔离 / WireGuard 加密 / cgroup 限制 / Sidecar 拦截 / 流量审计</li></ul><h3 id="_1-6-footer" tabindex="-1">1.6 Footer <a class="header-anchor" href="#_1-6-footer" aria-label="Permalink to &quot;1.6 Footer&quot;">​</a></h3><p>保持现有结构不变（logo + copyright + 链接）。</p><hr><h2 id="二、dashboard-新增内容" tabindex="-1">二、Dashboard 新增内容 <a class="header-anchor" href="#二、dashboard-新增内容" aria-label="Permalink to &quot;二、Dashboard 新增内容&quot;">​</a></h2><h3 id="_2-1-侧边栏" tabindex="-1">2.1 侧边栏 <a class="header-anchor" href="#_2-1-侧边栏" aria-label="Permalink to &quot;2.1 侧边栏&quot;">​</a></h3><p>在 &quot;AI Assistant&quot; 分组后新增 &quot;Agent 沙箱&quot; 分组:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────┐</span></span>
<span class="line"><span>│ 🛡️ Agent 沙箱               │</span></span>
<span class="line"><span>│   沙箱列表    /sandbox       │</span></span>
<span class="line"><span>│   接入令牌    /sandbox/tokens │</span></span>
<span class="line"><span>│   流量审计    /sandbox/audit  │</span></span>
<span class="line"><span>└─────────────────────────────┘</span></span></code></pre></div><p><strong>i18n key</strong>: <code>common.nav.group.sandbox</code>, <code>common.nav.sandboxList</code>, <code>common.nav.sandboxTokens</code>, <code>common.nav.sandboxAudit</code></p><h3 id="_2-2-dashboard-首页" tabindex="-1">2.2 Dashboard 首页 <a class="header-anchor" href="#_2-2-dashboard-首页" aria-label="Permalink to &quot;2.2 Dashboard 首页&quot;">​</a></h3><p>在现有 4 张统计卡片同行新增第 5 张：</p><table tabindex="0"><thead><tr><th>卡片</th><th>指标</th><th>图标</th><th>颜色</th></tr></thead><tbody><tr><td>Active Sandboxes</td><td>运行中沙箱数 (在线/total)，sparkline</td><td><code>Bot</code> 或 <code>Container</code></td><td>violet</td></tr></tbody></table><p><strong>数据来源</strong>: <code>GET /api/v1/agent-isolation/agents</code> 聚合统计。</p><h3 id="_2-3-新增页面-沙箱列表-sandbox" tabindex="-1">2.3 新增页面：沙箱列表 <code>/sandbox</code> <a class="header-anchor" href="#_2-3-新增页面-沙箱列表-sandbox" aria-label="Permalink to &quot;2.3 新增页面：沙箱列表 \`/sandbox\`&quot;">​</a></h3><p><strong>表格列</strong>: 名称, 状态(online/offline), 隔离模式(gVisor/cgroup), VPN IP, Sandbox ID, 流量 Rx/Tx, 创建时间, 操作(吊销)</p><p><strong>操作</strong>: 吊销按钮触发 <code>DELETE /api/v1/agent-isolation/agents/:name</code>，弹出确认框。</p><p><strong>状态颜色</strong>: online → emerald, offline → muted</p><p><strong>i18n key</strong>: <code>sandbox.list.title</code>, <code>sandbox.list.desc</code>, <code>sandbox.list.col*</code>, <code>sandbox.list.revoke</code>, <code>sandbox.list.confirmRevoke</code></p><h3 id="_2-4-新增页面-接入令牌-sandbox-tokens" tabindex="-1">2.4 新增页面：接入令牌 <code>/sandbox/tokens</code> <a class="header-anchor" href="#_2-4-新增页面-接入令牌-sandbox-tokens" aria-label="Permalink to &quot;2.4 新增页面：接入令牌 \`/sandbox/tokens\`&quot;">​</a></h3><p><strong>上半部分</strong>: 创建令牌表单</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>TTL</td><td>select/number</td><td>1h / 6h / 24h / Custom</td></tr><tr><td>Allowed Tools</td><td>multi-select checkbox</td><td>list_peers, list_policies, check_connectivity, ...</td></tr></tbody></table><p>创建按钮调用 <code>POST /api/v1/agent-isolation/enrollment-tokens</code>，成功后展示一次性 token（复制按钮 + 警告&quot;仅此一次可见&quot;）。</p><p><strong>下半部分</strong>: 令牌列表表格</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Token (masked)</td><td><code>a1b2c3...xxxx</code></td></tr><tr><td>创建时间</td><td>timestamp</td></tr><tr><td>过期时间</td><td>timestamp</td></tr><tr><td>状态</td><td>active / expired / revoked</td></tr><tr><td>操作</td><td>撤销 (DELETE)</td></tr></tbody></table><h3 id="_2-5-新增页面-流量审计-sandbox-audit" tabindex="-1">2.5 新增页面：流量审计 <code>/sandbox/audit</code> <a class="header-anchor" href="#_2-5-新增页面-流量审计-sandbox-audit" aria-label="Permalink to &quot;2.5 新增页面：流量审计 \`/sandbox/audit\`&quot;">​</a></h3><p><strong>内容</strong>: Agent 流量事件表，来自 <code>GET /api/v1/audit?type=traffic</code></p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>时间</td><td>timestamp</td></tr><tr><td>沙箱名称</td><td>identity/sandbox name</td></tr><tr><td>源 IP</td><td>src_ip</td></tr><tr><td>目标 IP:Port</td><td>dst_ip:dst_port</td></tr><tr><td>协议</td><td>tcp/udp</td></tr><tr><td>Verdict</td><td>allow (emerald) / drop (rose)</td></tr><tr><td>详情</td><td>展开查看完整 event JSON</td></tr></tbody></table><p><strong>过滤</strong>: 搜索框（按沙箱名/dst_ip），verdict 下拉过滤（allow/drop/all），时间范围选择。</p><p><strong>i18n key</strong>: <code>sandbox.audit.title</code>, <code>sandbox.audit.desc</code>, <code>sandbox.audit.col*</code>, <code>sandbox.audit.filter*</code></p><hr><h2 id="三、routes-汇总" tabindex="-1">三、Routes 汇总 <a class="header-anchor" href="#三、routes-汇总" aria-label="Permalink to &quot;三、Routes 汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路由</th><th>页面</th><th>meta layout</th></tr></thead><tbody><tr><td><code>/</code></td><td>pages/index.vue (Home)</td><td><code>blank</code> (不变)</td></tr><tr><td><code>/dashboard</code></td><td>pages/dashboard/index.vue</td><td><code>default</code> (不变)</td></tr><tr><td><code>/sandbox</code></td><td>pages/sandbox/index.vue (新增)</td><td><code>default</code></td></tr><tr><td><code>/sandbox/tokens</code></td><td>pages/sandbox/tokens.vue (新增)</td><td><code>default</code></td></tr><tr><td><code>/sandbox/audit</code></td><td>pages/sandbox/audit.vue (新增)</td><td><code>default</code></td></tr></tbody></table><hr><h2 id="四、文件变更清单" tabindex="-1">四、文件变更清单 <a class="header-anchor" href="#四、文件变更清单" aria-label="Permalink to &quot;四、文件变更清单&quot;">​</a></h2><h3 id="修改文件" tabindex="-1">修改文件 <a class="header-anchor" href="#修改文件" aria-label="Permalink to &quot;修改文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>变更内容</th></tr></thead><tbody><tr><td><code>fronted/src/pages/index.vue</code></td><td>按本文档第一节重写全部区块</td></tr><tr><td><code>fronted/src/locales/en/landing.json</code></td><td>更新/新增所有 landing i18n keys</td></tr><tr><td><code>fronted/src/locales/zh-CN/landing.json</code></td><td>同上</td></tr><tr><td><code>fronted/src/locales/en/common.json</code></td><td>新增 sandbox 相关 i18n keys</td></tr><tr><td><code>fronted/src/locales/zh-CN/common.json</code></td><td>同上</td></tr><tr><td><code>fronted/src/components/app-sidebar/AppSidebar.vue</code></td><td>新增 Agent 沙箱导航分组</td></tr><tr><td><code>fronted/src/pages/dashboard/index.vue</code></td><td>新增第 5 张统计卡片 (Active Sandboxes)</td></tr></tbody></table><h3 id="新增文件" tabindex="-1">新增文件 <a class="header-anchor" href="#新增文件" aria-label="Permalink to &quot;新增文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>fronted/src/pages/sandbox/index.vue</code></td><td>沙箱列表页</td></tr><tr><td><code>fronted/src/pages/sandbox/tokens.vue</code></td><td>接入令牌管理页</td></tr><tr><td><code>fronted/src/pages/sandbox/audit.vue</code></td><td>Agent 流量审计页</td></tr><tr><td><code>fronted/src/stores/useSandboxStore.ts</code></td><td>沙箱相关状态管理</td></tr></tbody></table><hr><h2 id="五、实现顺序" tabindex="-1">五、实现顺序 <a class="header-anchor" href="#五、实现顺序" aria-label="Permalink to &quot;五、实现顺序&quot;">​</a></h2><ol><li><strong>i18n keys</strong>: 先补全所有 <code>landing.*</code> 和 <code>sandbox.*</code> 的 i18n keys (中英文)</li><li><strong>Sidebar</strong>: 新增 Agent 沙箱导航分组</li><li><strong>Home 页重写</strong>: 按区块顺序实现 (Hero → Features → Architecture → Pricing → CTA → Footer)</li><li><strong>Dashboard 更新</strong>: 新增第 5 张卡片 + store 扩展</li><li><strong>新增页面</strong>: 沙箱列表 → 接入令牌 → 流量审计 (顺序依依赖)</li></ol>`,77)])])}const b=a(s,[["render",o]]);export{g as __pageData,b as default};
